enum ColorSyncDataDepth {
  kColorSync1BitGamut(1),
  kColorSync8BitInteger(2),
  kColorSync16BitInteger(3),
  kColorSync16BitFloat(4),
  kColorSync32BitInteger(5),
  kColorSync32BitNamedColorIndex(6),
  kColorSync32BitFloat(7),
  kColorSync10BitInteger(8);

  final int value;
  const ColorSyncDataDepth(this.value);

  static ColorSyncDataDepth fromValue(int value) => switch (value) {
    1 => kColorSync1BitGamut,
    2 => kColorSync8BitInteger,
    3 => kColorSync16BitInteger,
    4 => kColorSync16BitFloat,
    5 => kColorSync32BitInteger,
    6 => kColorSync32BitNamedColorIndex,
    7 => kColorSync32BitFloat,
    8 => kColorSync10BitInteger,
    _ => throw ArgumentError('Unknown value for ColorSyncDataDepth: $value'),
  };
}

